const MACRO_NAME = "The Lidless Eye";
const RANGE_METERS = 15;

const getSpeakerActor = () => {
  const speaker = ChatMessage.getSpeaker();
  if (speaker.token) {
    const token = canvas.tokens?.get(speaker.token);
    if (token?.actor) return token.actor;
  }
  if (speaker.actor) return game.actors?.get(speaker.actor);
  return null;
};

const getSpeakerToken = () => {
  if (canvas.tokens?.controlled?.length) return canvas.tokens.controlled[0];
  const speaker = ChatMessage.getSpeaker();
  if (speaker.token) return canvas.tokens?.get(speaker.token) ?? null;
  return null;
};

const clampTarget = (base, modifier) => {
  const capped = Math.max(-60, Math.min(60, modifier));
  return base + capped;
};

const computeDegrees = (target, rollTotal) => {
  const success = rollTotal <= target;
  if (success) {
    const degree = Math.floor(target / 10) - Math.floor(rollTotal / 10);
    return { success: true, dos: Math.max(1 + degree, 1), dof: 0 };
  }
  const degree = Math.floor(rollTotal / 10) - Math.floor(target / 10);
  return { success: false, dos: 0, dof: Math.max(1 + degree, 1) };
};

const degreeScore = degrees => (degrees.success ? degrees.dos : -degrees.dof);

const getTokenCenter = token => {
  if (token?.center) return token.center;
  if (typeof token?.getCenter === "function") return token.getCenter();
  return null;
};

const isWallBlocking = (origin, target) => {
  const walls = canvas.walls;
  if (!walls || !origin || !target) return false;
  const ray = new Ray(origin, target);
  return walls.checkCollision(ray, { type: "sight", mode: "any" });
};

const measureDistance = (origin, target) => {
  const grid = canvas.grid;
  if (!grid) return Number.POSITIVE_INFINITY;
  return grid.measureDistance(origin, target);
};

const highlightTargets = tokens => {
  tokens.forEach(token => token.setTarget(true, { releaseOthers: false }));
};

const clearHighlights = tokens => {
  tokens.forEach(token => token.setTarget(false, { releaseOthers: false }));
};

const createTempLight = async (origin, angle, emission) => {
  const data = {
    x: origin.x,
    y: origin.y,
    rotation: angle,
    config: {
      dim: RANGE_METERS,
      bright: RANGE_METERS,
      angle: emission,
      animation: { type: "radialrainbow", speed: 5, intensity: 5 }
    }
  };
  const created = await canvas.scene.createEmbeddedDocuments("AmbientLight", [data]);
  return created?.[0] ?? null;
};

const removeTempLight = async light => {
  if (!light) return;
  await canvas.scene.deleteEmbeddedDocuments("AmbientLight", [light.id]);
};

const createTempTemplate = async (origin, angle, emission) => {
  const type = emission >= 360 ? "circle" : "cone";
  const data = {
    t: type,
    user: game.user.id,
    x: origin.x,
    y: origin.y,
    distance: RANGE_METERS,
    direction: angle,
    angle: emission,
    fillColor: "#7a5cff",
    borderColor: "#c6b0ff",
    flags: { "lidless-eye": true }
  };
  const created = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [data]);
  return created?.[0] ?? null;
};

const removeTempTemplate = async template => {
  if (!template) return;
  await canvas.scene.deleteEmbeddedDocuments("MeasuredTemplate", [template.id]);
};

const pickAngle = origin => new Promise(resolve => {
  ui.notifications.info("Click on the canvas to set the emission angle.");
  const handler = event => {
    const { x, y } = event.data.global;
    const dx = x - origin.x;
    const dy = y - origin.y;
    const angle = (Math.atan2(dy, dx) * 180) / Math.PI;
    canvas.stage.off("pointerdown", handler);
    resolve((angle + 360) % 360);
  };
  canvas.stage.on("pointerdown", handler);
});

const buildDialog = (actor, config) => new Promise(resolve => {
  const content = `
    <div class="lidless-eye">
      <h2>${MACRO_NAME}</h2>
      <p>Warp Eye emission within ${RANGE_METERS}m. Walls block line of effect.</p>
      <div class="form-group">
        <label>Navigator Willpower</label>
        <input type="text" value="${actor.characteristics?.willpower?.total ?? 0}" disabled />
      </div>
      <div class="form-group">
        <label>Navigator WP Modifier</label>
        <input type="number" name="navigatorModifier" value="0" />
      </div>
      <div class="form-group">
        <label>Emission Degrees</label>
        <input type="number" name="emission" value="${config.emission}" min="30" max="360" step="10" />
      </div>
      <div class="form-group">
        <label>Emission Angle</label>
        <input type="text" name="angle" value="${config.angle}" disabled />
        <button type="button" class="pick-angle">Pick Direction</button>
      </div>
      <div class="form-group">
        <label>Power Level</label>
        <select name="level">
          <option value="novice">Novice</option>
          <option value="adept">Adept</option>
          <option value="master">Master</option>
        </select>
      </div>
    </div>`;
  new Dialog({
    title: MACRO_NAME,
    content,
    buttons: {
      cast: {
        icon: "<i class=\"fa-solid fa-eye\"></i>",
        label: "Cast",
        callback: html => {
          resolve({
            navigatorModifier: Number(html.find("[name=navigatorModifier]").val() ?? 0),
            emission: Number(html.find("[name=emission]").val() ?? 360),
            angle: config.angle,
            level: html.find("[name=level]").val()
          });
        }
      },
      cancel: {
        icon: "<i class=\"fa-solid fa-times\"></i>",
        label: "Cancel",
        callback: () => resolve(null)
      }
    },
    render: html => {
      html.find(".pick-angle").on("click", async () => {
        const angle = await pickAngle(config.origin);
        config.angle = angle;
        html.find("[name=angle]").val(angle);
      });
    },
    default: "cast"
  }).render(true);
});

const withinCone = (origin, target, angle, emission) => {
  if (emission >= 360) return true;
  const dx = target.x - origin.x;
  const dy = target.y - origin.y;
  const targetAngle = ((Math.atan2(dy, dx) * 180) / Math.PI + 360) % 360;
  let delta = Math.abs(targetAngle - angle);
  if (delta > 180) delta = 360 - delta;
  return delta <= (emission / 2);
};

const applyRawDamage = async (actor, amount) => {
  const wounds = actor.system.wounds.value;
  const maxWounds = actor.system.wounds.max;
  let critical = actor.system.wounds.critical;
  let newWounds = wounds + amount;
  let newCritical = critical;
  if (newWounds > maxWounds) {
    newCritical += (newWounds - maxWounds);
    newWounds = maxWounds;
  }
  await actor.update({
    "system.wounds.value": newWounds,
    "system.wounds.critical": newCritical
  });
};

const applyStatusEffect = async (actor, statusId, rounds) => {
  const effectData = CONFIG.statusEffects?.find(entry => entry.id === statusId);
  if (!effectData) return;
  if (rounds && rounds > 0) {
    const effect = {
      label: game.i18n?.localize?.(effectData.label) ?? effectData.label,
      icon: effectData.icon,
      changes: [],
      duration: {
        rounds,
        startRound: game.combat?.round ?? 0,
        startTime: game.time?.worldTime ?? 0
      },
      flags: { core: { statusId } }
    };
    await actor.createEmbeddedDocuments("ActiveEffect", [effect]);
  } else {
    await actor.toggleStatusEffect(statusId, { active: true });
  }
};

const applyFatigue = async (actor, levels) => {
  const current = Number(actor.system.fatigue.value ?? 0);
  await actor.update({ "system.fatigue.value": current + levels });
  return current + levels;
};

const applyInsanity = async (actor, amount) => {
  const current = Number(actor.system.insanity ?? 0);
  await actor.update({ "system.insanity": current + amount });
  return current + amount;
};

const actor = getSpeakerActor();
const originToken = getSpeakerToken();
if (!actor || !originToken) {
  ui.notifications.warn(`${MACRO_NAME}: Select a Navigator token first.`);
  return;
}

const origin = getTokenCenter(originToken);
if (!origin) {
  ui.notifications.warn(`${MACRO_NAME}: Unable to find origin.`);
  return;
}

const config = { origin, angle: 0, emission: 360 };
const dialogResult = await buildDialog(actor, config);
if (!dialogResult) return;

const emission = Math.max(30, Math.min(360, dialogResult.emission));
const angle = dialogResult.angle ?? 0;
const level = dialogResult.level ?? "novice";

const tokens = canvas.tokens?.placeables ?? [];
const candidates = tokens.filter(token => token?.actor && token.id !== originToken.id);
const blockedTargets = [];
const inRange = candidates.filter(token => {
  const center = getTokenCenter(token);
  if (!center) return false;
  const distance = measureDistance(origin, center);
  if (distance > RANGE_METERS) return false;
  if (!withinCone(origin, center, angle, emission)) return false;
  if (isWallBlocking(origin, center)) {
    blockedTargets.push(token.name);
    return false;
  }
  return true;
});

highlightTargets(inRange);
const tempLight = await createTempLight(origin, angle, emission);
const tempTemplate = await createTempTemplate(origin, angle, emission);

const navigatorWp = actor.characteristics?.willpower?.total ?? 0;
const navigatorTarget = clampTarget(navigatorWp, dialogResult.navigatorModifier);
const navigatorRoll = await new Roll("1d100").evaluate({ async: true });
const navigatorDegrees = computeDegrees(navigatorTarget, navigatorRoll.total);

await navigatorRoll.toMessage({
  speaker: ChatMessage.getSpeaker({ actor, token: originToken.document }),
  flavor: `${MACRO_NAME}: ${actor.name} Willpower vs ${navigatorTarget} (${dialogResult.navigatorModifier >= 0 ? "+" : ""}${dialogResult.navigatorModifier})`
});

const summaryLines = [
  `<strong>${MACRO_NAME}</strong>`,
  `Level: ${level.toUpperCase()}`,
  `${actor.name}: ${navigatorRoll.total} vs ${navigatorTarget} → ${navigatorDegrees.success ? "Success" : "Failure"} (${navigatorDegrees.dos} DoS${navigatorDegrees.dof ? `, ${navigatorDegrees.dof} DoF` : ""})`,
  `Targets in cone: ${inRange.map(t => t.name).join(", ") || "None"}`
];
if (blockedTargets.length) {
  summaryLines.push(`Blocked by walls: ${blockedTargets.join(", ")}`);
}

let fatigueGain = navigatorDegrees.success ? 1 : 2;
let totalFatigue = await applyFatigue(actor, fatigueGain);
summaryLines.push(`${actor.name} gains ${fatigueGain} Fatigue (Total: ${totalFatigue}).`);

for (const targetToken of inRange) {
  const targetActor = targetToken.actor;
  const targetWp = targetActor.characteristics?.willpower?.total ?? 0;
  const targetRoll = await new Roll("1d100").evaluate({ async: true });
  const targetDegrees = computeDegrees(targetWp, targetRoll.total);

  await targetRoll.toMessage({
    speaker: ChatMessage.getSpeaker({ actor: targetActor, token: targetToken.document }),
    flavor: `${MACRO_NAME}: ${targetToken.name} Willpower vs ${targetWp}`
  });

  const net = degreeScore(navigatorDegrees) - degreeScore(targetDegrees);
  const line = `${targetToken.name}: ${targetRoll.total} vs ${targetWp} → ${targetDegrees.success ? "Success" : "Failure"} (${targetDegrees.dos} DoS${targetDegrees.dof ? `, ${targetDegrees.dof} DoF` : ""}) | Difference: ${net}`;
  summaryLines.push(line);

  if (net <= 0) continue;

  const action = await new Promise(resolve => {
    const content = `
      <p>${targetToken.name} is affected. Difference: ${net} DoS.</p>
      <div class="form-group">
        <label>Deny WP Modifier</label>
        <input type="number" name="denyModifier" value="0" />
      </div>`;
    new Dialog({
      title: `${MACRO_NAME}: ${targetToken.name}`,
      content,
      buttons: {
        apply: {
          icon: "<i class=\"fa-solid fa-bolt\"></i>",
          label: "Apply Damage",
          callback: html => resolve({
            type: "apply",
            denyModifier: Number(html.find("[name=denyModifier]").val() ?? 0),
            adjust: 0
          })
        },
        deny: {
          icon: "<i class=\"fa-solid fa-ban\"></i>",
          label: "Deny",
          callback: html => resolve({
            type: "deny",
            denyModifier: Number(html.find("[name=denyModifier]").val() ?? 0),
            adjust: 0
          })
        },
        modify: {
          icon: "<i class=\"fa-solid fa-wand-magic\"></i>",
          label: "Modify",
          callback: html => resolve({
            type: "modify",
            denyModifier: Number(html.find("[name=denyModifier]").val() ?? 0),
            adjust: null
          })
        }
      },
      default: "apply"
    }).render(true);
  });

  let finalNet = net;
  if (action.type === "deny") {
    const denyTarget = clampTarget(targetWp, action.denyModifier);
    const denyRoll = await new Roll("1d100").evaluate({ async: true });
    await denyRoll.toMessage({
      speaker: ChatMessage.getSpeaker({ actor: targetActor, token: targetToken.document }),
      flavor: `${MACRO_NAME}: ${targetToken.name} Deny vs ${denyTarget} (${action.denyModifier >= 0 ? "+" : ""}${action.denyModifier})`
    });
    const denyDegrees = computeDegrees(denyTarget, denyRoll.total);
    if (denyDegrees.success) {
      summaryLines.push(`${targetToken.name} denied the power.`);
      continue;
    }
  }

  if (action.type === "modify") {
    const adjust = await new Promise(resolve => {
      new Dialog({
        title: `${MACRO_NAME}: Modify Difference`,
        content: `<div class="form-group"><label>Adjust Difference</label><input type="number" name="adjust" value="0" /></div>`,
        buttons: {
          apply: {
            icon: "<i class=\"fa-solid fa-check\"></i>",
            label: "Apply",
            callback: html => resolve(Number(html.find("[name=adjust]").val() ?? 0))
          }
        },
        default: "apply"
      }).render(true);
    });
    finalNet = net + adjust;
  }

  if (finalNet <= 0) {
    summaryLines.push(`${targetToken.name} resists after modifiers.`);
    continue;
  }

  let damageFormula = `1d10 + ${actor.characteristics?.willpower?.bonus ?? 0}`;
  let stunRoll = new Roll("1d1");
  let insanityAmount = null;

  if (level === "adept") {
    damageFormula = `2d10 + ${actor.characteristics?.willpower?.bonus ?? 0}`;
    stunRoll = new Roll("1d5");
  }
  if (level === "master") {
    damageFormula = `2d10 + ${actor.characteristics?.willpower?.bonus ?? 0}`;
    stunRoll = new Roll("1d5");
  }

  const damageRoll = await new Roll(damageFormula).evaluate({ async: true });
  await damageRoll.toMessage({
    speaker: ChatMessage.getSpeaker({ actor, token: originToken.document }),
    flavor: `${MACRO_NAME}: Damage to ${targetToken.name} (${damageFormula})`
  });
  await applyRawDamage(targetActor, damageRoll.total);

  const stunRounds = (await stunRoll.evaluate({ async: true })).total;
  await applyStatusEffect(targetActor, "stunned", stunRounds);
  summaryLines.push(`${targetToken.name} takes ${damageRoll.total} Energy damage (no armour/TB) and is Stunned ${stunRounds} rounds.`);

  if (level === "adept" || level === "master") {
    const intScore = targetActor.characteristics?.intelligence?.total ?? 0;
    if (level === "master" && intScore >= 20) {
      const toughTarget = clampTarget(targetActor.characteristics?.toughness?.total ?? 0, -10);
      const toughRoll = await new Roll("1d100").evaluate({ async: true });
      await toughRoll.toMessage({
        speaker: ChatMessage.getSpeaker({ actor: targetActor, token: targetToken.document }),
        flavor: `${MACRO_NAME}: ${targetToken.name} Toughness (Difficult -10) vs ${toughTarget}`
      });
      const toughDegrees = computeDegrees(toughTarget, toughRoll.total);
      if (!toughDegrees.success) {
        await applyStatusEffect(targetActor, "dead");
        summaryLines.push(`${targetToken.name} is slain by the Warp Eye.`);
        continue;
      }
      insanityAmount = (await new Roll("1d10").evaluate({ async: true })).total;
    } else {
      insanityAmount = (await new Roll("1d5").evaluate({ async: true })).total;
    }
    const totalInsanity = await applyInsanity(targetActor, insanityAmount);
    summaryLines.push(`${targetToken.name} gains ${insanityAmount} Insanity (Total: ${totalInsanity}).`);
  }
}

await ChatMessage.create({
  speaker: ChatMessage.getSpeaker({ actor, token: originToken.document }),
  content: `<div class="dh-roll">${summaryLines.map(line => `<p>${line}</p>`).join("")}</div>`
});

setTimeout(async () => {
  clearHighlights(inRange);
  await removeTempLight(tempLight);
  await removeTempTemplate(tempTemplate);
}, 5000);
